// Local prototype service layer. UI permissions are not production security.
window.Maxis=(()=>{
 const key='maxis-learning-impact-v3';let state;let loadWarning='';
 try{const saved=localStorage.getItem(key);state=saved?JSON.parse(saved):MaxisSeed();if(state.version!==3||!Array.isArray(state.people)||!Array.isArray(state.modules))throw Error('Unsupported data');}catch{state=MaxisSeed();loadWarning='Saved demo data could not be loaded. A fresh demo is shown.';}
 const copy=x=>JSON.parse(JSON.stringify(x));const uid=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
 const findPerson=id=>state.people.find(p=>p.id===id);const findModule=id=>state.modules.find(m=>m.id===id);const findSession=id=>state.sessions.find(s=>s.id===id);
 const actor=(role,id)=>{if(role==='participant'){const p=findPerson(id);if(!p||!p.access)throw Error('Participant access is disabled.');return {role,id,name:p.name};}const u=state.users.find(u=>u.id===id&&u.role===role&&u.active);if(!u)throw Error('This user has no active access.');return u;};
 const scope=(a,p)=>a.role==='participant'?p.id===a.id:a.role==='admin'||a.cohorts.includes(p.cohort);
 const canEdit=(a,p)=>a.role==='admin'||(a.role==='mentor'&&scope(a,p)&&p.mentor===a.id);
 const people=a=>state.people.filter(p=>scope(a,p));const available=p=>state.modules.filter(m=>m.published&&m.programmes.includes(p.programme)&&p.moduleIds.includes(m.id));
 const record=(p,m)=>{const r=p.learning[m.id];return r&&r.revision===m.revision?r:{revision:m.revision,reviewed:[],notes:r?.notes||{},attempts:[]};};
 const progress=(p,m)=>{const r=record(p,m);const reviewed=m.resources.filter(x=>r.reviewed.includes(x.id)).length;const best=r.attempts.length?Math.max(...r.attempts.map(a=>a.score)):null;const passed=r.attempts.some(a=>a.passed);const complete=reviewed===m.resources.length&&passed;const percent=Math.round((reviewed+(passed?1:0))/(m.resources.length+1)*100);return {reviewed,total:m.resources.length,best,passed,complete,percent,attempts:r.attempts};};
 const pathway=p=>{const ms=available(p);const done=ms.filter(m=>progress(p,m).complete).length;const started=ms.some(m=>progress(p,m).percent>0);return{total:ms.length,done,complete:ms.length>0&&done===ms.length,percent:ms.length?Math.round(done/ms.length*100):0,started};};
 const attendance=(p,cutoff='9999-12-31')=>{const ss=state.sessions.filter(s=>s.finalized&&s.date<=cutoff&&s.roster.includes(p.id));const present=ss.filter(s=>s.marks[p.id]==='present').length;return{present,total:ss.length,percent:ss.length?Math.round(present/ss.length*100):null};};
 const classProgress=p=>{const x=attendance(p);const required=Number(p.classTarget)||0;return {attended:x.present,required,complete:required>0&&x.present>=required};};
 const filtered=(a,f={})=>people(a).filter(p=>['programme','cohort','state','gender'].every(k=>!f[k]||f[k]==='all'||p[k]===f[k]));
 const stats=(a,f={})=>{const ps=filtered(a,f);const completed=ps.filter(p=>pathway(p).complete).length;let moduleDone=0,moduleTotal=0,present=0,opportunities=0;ps.forEach(p=>{const l=pathway(p);moduleDone+=l.done;moduleTotal+=l.total;const att=attendance(p);present+=att.present;opportunities+=att.total;});const month=f.month||'2026-09';const reported=ps.map(p=>({p,c:p.checkins.find(c=>c.month===month)})).filter(x=>x.c);const comparable=reported.filter(x=>x.p.baseline&&x.p.baseline.sales-x.p.baseline.cost>0);const base=comparable.reduce((v,x)=>v+x.p.baseline.sales-x.p.baseline.cost,0);const follow=comparable.reduce((v,x)=>v+x.c.sales-x.c.cost,0);const cohortIds=new Set(ps.map(p=>p.cohort));const sessions=state.sessions.filter(s=>s.finalized&&cohortIds.has(s.cohort)&&(f.programme==='all'||!f.programme||s.programme===f.programme));return {ps,count:ps.length,classCompleted:ps.filter(p=>classProgress(p).complete).length,completed,moduleDone,moduleTotal,started:ps.filter(p=>pathway(p).started).length,attendance:opportunities?Math.round(present/opportunities*100):null,finalizedClasses:sessions.length,reporting:reported.length,average:reported.length?Math.round(reported.reduce((v,x)=>v+x.c.sales-x.c.cost,0)/reported.length):null,growth:base?Math.round((follow-base)/base*100):null,comparable:comparable.length,reported};};
 function change(a,label,fn){const before=copy(state);try{const result=fn();state.audit.unshift({at:new Date().toISOString(),by:a.name,action:label});state.audit=state.audit.slice(0,80);localStorage.setItem(key,JSON.stringify(state));return result;}catch(e){state=before;throw e;}}
 const admin=a=>{if(a.role!=='admin')throw Error('Only programme admins can do this.');};
 const learn=(a,id)=>{if(a.role!=='participant')throw Error('Switch to a participant to study.');const p=findPerson(a.id),m=findModule(id);if(!m||!available(p).some(x=>x.id===id))throw Error('This module is not assigned or published.');p.learning[m.id]=record(p,m);return{p,m,r:p.learning[m.id]};};
 return {get state(){return state},get loadWarning(){return loadWarning},actor,scope,canEdit,people,available,record,progress,pathway,attendance,classProgress,filtered,stats,findPerson,findModule,findSession,uid,
 markResource(a,id,rid){return change(a,'Studied learning resource',()=>{const {m,r}=learn(a,id);if(!m.resources.some(x=>x.id===rid))throw Error('Unknown resource.');if(!r.reviewed.includes(rid))r.reviewed.push(rid);});},
 saveNote(a,id,rid,note){return change(a,'Saved private learning note',()=>{const {m,r}=learn(a,id);if(!m.resources.some(x=>x.id===rid))throw Error('Unknown resource.');r.notes[rid]=String(note).slice(0,10000);});},
 submitQuiz(a,id,answers){return change(a,'Submitted module quiz',()=>{const {p,m,r}=learn(a,id);if(!m.resources.every(x=>r.reviewed.includes(x.id)))throw Error('Study all resources before taking the quiz.');if(answers.length!==m.quiz.length||answers.some((v,i)=>!Number.isInteger(v)||v<0||v>=m.quiz[i].options.length))throw Error('Answer every question.');const score=Math.round(answers.filter((v,i)=>v===m.quiz[i].correct).length/m.quiz.length*100);const attempt={score,passed:score>=m.passMark,date:new Date().toISOString(),answers};r.attempts.push(attempt);return attempt;});},
 savePerson(a,input,id){admin(a);return change(a,id?'Updated participant and access':'Added participant',()=>{if(!input.name?.trim()||!input.business?.trim())throw Error('Enter participant and business names.');if(!state.programmes.includes(input.programme)||!state.cohorts.some(c=>c.id===input.cohort))throw Error('Choose a valid programme and cohort.');const mentor=state.users.find(u=>u.id===input.mentor&&u.role==='mentor'&&u.active&&u.cohorts.includes(input.cohort));if(!mentor)throw Error('Choose a mentor who has access to this cohort.');if(!Number.isInteger(input.classTarget)||input.classTarget<1||input.classTarget>100)throw Error('Required classes must be between 1 and 100.');if(input.baseline&&(![input.baseline.sales,input.baseline.cost].every(v=>Number.isFinite(v)&&v>=0)))throw Error('Baseline figures must be nonnegative.');if(input.email&&state.people.some(p=>p.id!==id&&p.email.toLowerCase()===input.email.toLowerCase()))throw Error('This email is already attached to a participant.');const validIds=state.modules.filter(m=>m.programmes.includes(input.programme)).map(m=>m.id);if(input.moduleIds.some(mid=>!validIds.includes(mid)))throw Error('Module programme does not match participant.');let p=id?findPerson(id):null;if(id&&!p)throw Error('Participant not found.');if(!p){p={id:uid('EKU'),learning:{},checkins:[],photo:''};state.people.push(p);}Object.assign(p,input,{name:input.name.trim(),business:input.business.trim()});return p.id;});},
 saveCheckin(a,id,input){const p=findPerson(id);if(!p||!(canEdit(a,p)||(a.role==='participant'&&a.id===id)))throw Error('You cannot update this participant.');return change(a,'Saved monthly business check-in',()=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(input.month)||![input.sales,input.cost].every(v=>Number.isFinite(v)&&v>=0))throw Error('Enter a valid month and nonnegative sales/costs.');if(a.role==='participant')input.reviewed=false;const i=p.checkins.findIndex(x=>x.month===input.month);if(i>=0)p.checkins[i]=input;else p.checkins.push(input);p.checkins.sort((a,b)=>a.month.localeCompare(b.month));});},
 setPhoto(a,id,data){const p=findPerson(id);if(!p||!(a.role==='admin'||(a.role==='participant'&&a.id===id)))throw Error('Photo changes require participant or admin access.');if(data&&!/^data:image\/(jpeg|png|webp);base64,/.test(data))throw Error('Unsupported photo.');return change(a,'Updated profile photo',()=>p.photo=data);},
 saveModule(a,input,id){admin(a);return change(a,id?'Updated module revision':'Created learning module',()=>{if(!input.title?.trim()||!input.programmes.length||!input.programmes.every(p=>state.programmes.includes(p)))throw Error('Enter a title and valid programmes.');if(!Number.isFinite(input.passMark)||input.passMark<1||input.passMark>100||!Number.isFinite(input.duration)||input.duration<1)throw Error('Check pass mark and duration.');let m=id?findModule(id):null;if(id&&!m)throw Error('Module not found.');if(!m){m={id:uid('M'),resources:[],quiz:[],revision:1,color:'green'};state.modules.push(m);}if(id&&m.passMark!==input.passMark)m.revision++;Object.assign(m,input,{title:input.title.trim()});return m.id;});},
 setPublished(a,id,value){admin(a);return change(a,value?'Published module':'Unpublished module',()=>{const m=findModule(id);if(!m)throw Error('Module not found.');if(value&&(!m.resources.length||!m.quiz.length))throw Error('Add at least one learning resource and a quiz before publishing.');m.published=value;});},
 saveResource(a,id,input,rid){admin(a);return change(a,'Updated module resources',()=>{const m=findModule(id);if(!m||!input.title?.trim()||!['reading','video','workbook'].includes(input.type))throw Error('Check resource details.');if(input.type==='video'&&!safeVideo(input.url))throw Error('Enter an HTTPS video URL (MP4 or YouTube), or demo-lesson.mp4.');if(input.type!=='video'&&!input.body?.trim()&&!input.fileData)throw Error('Add reading content or upload a material.');if(input.fileData&&!/^data:application\/pdf;base64,/.test(input.fileData))throw Error('Upload a PDF workbook.');const resource={...input,id:rid||uid('R')};const i=m.resources.findIndex(r=>r.id===rid);if(i>=0)m.resources[i]=resource;else m.resources.push(resource);m.revision++;return resource.id;});},
 saveQuiz(a,id,questions){admin(a);return change(a,'Updated quiz revision',()=>{const m=findModule(id);if(!m||!questions.length||questions.some(q=>!q.prompt.trim()||q.options.length!==4||q.options.some(x=>!x.trim())||new Set(q.options.map(x=>x.trim())).size!==4||!Number.isInteger(q.correct)||q.correct<0||q.correct>3))throw Error('Each question needs four different answers and a correct answer.');m.quiz=questions;m.revision++;});},
 saveUser(a,input,id){admin(a);return change(a,'Updated staff access',()=>{if(!input.name.trim()||!['mentor','stakeholder'].includes(input.role)||!input.cohorts.length||!input.cohorts.every(c=>state.cohorts.some(x=>x.id===c)))throw Error('Enter a name, role and at least one valid cohort.');const u=id?state.users.find(x=>x.id===id):null;if(id&&!u)throw Error('User not found.');if(u?.role==='admin')throw Error('Admin access is fixed in this prototype.');if(u){const assigned=state.people.filter(p=>p.mentor===id);if(assigned.length&&(input.role!=='mentor'||!input.active||assigned.some(p=>!input.cohorts.includes(p.cohort))))throw Error('Reassign this mentor’s participants before removing their access.');Object.assign(u,input);}else state.users.push({...input,id:uid('U')});});},
 createSession(a,input){if(!['admin','mentor'].includes(a.role)||(a.role==='mentor'&&!a.cohorts.includes(input.cohort)))throw Error('No access to create this cohort session.');return change(a,'Created session register',()=>{if(!state.programmes.includes(input.programme)||!state.cohorts.some(c=>c.id===input.cohort)||!Number.isInteger(input.number)||input.number<1||input.number>999||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||Number.isNaN(Date.parse(input.date)))throw Error('Enter valid session details.');const duplicate=state.sessions.find(s=>s.programme===input.programme&&s.cohort===input.cohort&&s.number===input.number);if(duplicate)return duplicate.id;const roster=state.people.filter(p=>p.programme===input.programme&&p.cohort===input.cohort).map(p=>p.id);if(!roster.length)throw Error('No participants belong to this programme and cohort.');const s={...input,id:uid('S'),finalized:false,roster,marks:{}};state.sessions.push(s);return s.id;});},
 markAttendance(a,sid,pid,mark){return change(a,'Marked live attendance',()=>{const s=findSession(sid);sessionAccess(a,s);if(s.finalized)throw Error('Reopen this register before making changes.');refreshRoster(s);if(!s.roster.includes(pid)||!['present','absent','unmarked'].includes(mark))throw Error('Invalid attendance mark.');s.marks[pid]=mark;});},
 finalizeSession(a,sid){return change(a,'Finalized session register',()=>{const s=findSession(sid);sessionAccess(a,s);if(s.finalized)throw Error('Already finalized.');refreshRoster(s);if(!s.roster.length||s.roster.some(id=>!['present','absent'].includes(s.marks[id])))throw Error('Mark everyone present or absent before finalizing.');s.finalized=true;s.hasSnapshot=true;});},
 reopenSession(a,sid){return change(a,'Reopened attendance for correction',()=>{const s=findSession(sid);sessionAccess(a,s);s.finalized=false;});},
 sessionRoster(s){if(!s.finalized)refreshRoster(s);return s.roster.map(findPerson).filter(Boolean);},
 reset(){localStorage.removeItem(key);state=MaxisSeed();},safeVideo
 };
 function refreshRoster(s){if(s.hasSnapshot)return;const current=state.people.filter(p=>p.programme===s.programme&&p.cohort===s.cohort).map(p=>p.id);s.roster=[...new Set([...s.roster,...current])];}
 function sessionAccess(a,s){if(!s||!['admin','mentor'].includes(a.role)||(a.role==='mentor'&&!a.cohorts.includes(s.cohort)))throw Error('No access to edit this register.');}
 function safeVideo(raw){if(raw==='demo-lesson.mp4')return true;try{const u=new URL(raw);return u.protocol==='https:'&&(/\.mp4$/i.test(u.pathname)||['www.youtube.com','youtube.com','youtu.be'].includes(u.hostname));}catch{return false;}}
})();
